/** Contract tokens are generated by generateContractToken: 24 random bytes in hex. */
export function getContractTokenColumn(token: unknown) {
  if (typeof token !== "string" || token.length !== 52) return null;
  if (/^onb_[a-f0-9]{48}$/.test(token)) return "onboarding_token" as const;
  if (/^sgn_[a-f0-9]{48}$/.test(token)) return "signing_token" as const;
  return null;
}
